"""AQS-THM-002 ventilation and HVAC per room (X-THM-02, A-M-211). Room = sector on a level (AQS-BLD-013 rows). Floor area = equipment
footprint / 0.35 coverage (access aisles, A-M-211), scaled so a level never exceeds the plate. Height = storey height. Extract is the
largest of: (a) ASHRAE 62.1 area rate 0.30 L/s m2 (all rooms); (b) IFC 5004.3 hazardous-material exhaust 5.08 L/s m2 (rooms with an
AQS-ELEC-009 release source or a corrosive/toxic chemical in AQS-COM-001); (c) dilution of the room's H2 release to 25 % LFL with the
largest single-unit H2 rate (4 % LFL; NFPA 2); (d) the room's equipment heat over a 10 K rise. Make-up = 95 % of extract (room held
negative). Fan kW = Q dp / eta, dp 500 Pa extract, 400 Pa make-up, eta 0.6, duty + standby fan per room (X-RED). Run after _haz_area.py."""
import csv, json, os, sys, collections
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R); sys.path.insert(0, R)
from flow_graph.param.refs import cite
for k in ('ASHRAE621_2019', 'IFC2027_5004_3', 'NFPA2_2026', 'IEC60079_10_1'): cite(k)
g = json.load(open('flow_graph/plant_flow_graph.json')); N = {n['unit_id']: n for n in g['nodes']}
SR = json.load(open('docs-authority/inventory/STRUCT_ROWS.json')); HZ = {r['unit']: r for r in csv.DictReader(open('docs-authority/inventory/HAZ_AREA.csv'))}
CM = {r['unit']: r for r in csv.DictReader(open('docs-authority/inventory/COMMISSIONING.csv'))}
PLATE = 24*18; HT = {'L-2': 10.0, 'L-1': 6.0, 'L0': 6.0, 'L1': 6.0, 'L2': 4.8}
TOX = {'HCl', 'Cl2', 'NO', 'NOx', 'HNO3', 'NaOH', 'AcOH', 'CO'}
rooms = collections.defaultdict(lambda: dict(foot=0.0, units=[], h2=0.0, kw=0.0, haz=False))
for r in SR:
    lv = r['level']
    if lv not in HT: continue
    u = r['unit']; s = (N.get(u) or {}).get('sector_id') or 'OTHER'; k = (lv, s); R_ = rooms[k]
    R_['foot'] += r['foot_m2']; R_['units'].append(u); R_['kw'] += float(((N.get(u) or {}).get('continuous_kw') or {}).get('value') or 0)
    if u in HZ: R_['haz'] = True; R_['h2'] = max(R_['h2'], float(HZ[u]['kg_d']) if 'H2' in HZ[u]['substances'] else 0)
    if set((CM.get(u) or {}).get('chemicals', '').split()) & TOX: R_['haz'] = True
lvA = collections.defaultdict(float)
for (lv, s), R_ in rooms.items(): lvA[lv] += R_['foot']/0.35
out = []
for (lv, s), R_ in sorted(rooms.items()):
    A = R_['foot']/0.35*min(1.0, PLATE/lvA[lv]); V = A*HT[lv]
    qa = 0.30*A/1000; qb = 5.08*A/1000 if R_['haz'] else 0
    qc = (R_['h2']/86400/0.0899)/(0.25*0.04)                          # m3/s, H2 at 0.0899 kg/m3
    qd = R_['kw']*0.5/(1.2*1.005*10)                                  # half of electrical input as room heat (A-M-211)
    Q = max(qa, qb, qc, qd); gov = ['ASHRAE 62.1', 'IFC 5004.3', 'H2 dilution', 'heat'][[qa, qb, qc, qd].index(Q)]
    fan = (Q*500 + 0.95*Q*400)/0.6/1000
    out.append(dict(room=f'{lv} {s}', level=lv, sector=s, units=len(R_['units']), area_m2=round(A, 1), volume_m3=round(V), hazardous='yes' if R_['haz'] else 'no',
                    extract_m3_h=round(Q*3600), ach=round(Q*3600/V, 1) if V else 0, makeup_m3_h=round(0.95*Q*3600), governs=gov, fan_kW=round(fan, 3), fans='2 x 100 % extract, 2 x 100 % make-up'))
with open('docs-authority/inventory/HVAC_ROOMS.csv', 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=list(out[0])); w.writeheader(); w.writerows(out)
md = ['# Ventilation and HVAC design', '', 'Document number: AQS-THM-002', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-THM-02. Generated by `docs-authority/_hvac.py`. Study. A-M-211.', '',
 'Extract per room = max(ASHRAE 62.1 0.30 L/s m2; IFC 5004.3 5.08 L/s m2 where hazardous; H2 dilution to 25 % LFL; equipment heat at 10 K). Make-up 95 % (negative room). Hazardous-room extract inlets low for vapours and high for H2 (AQS-ELEC-009). Loss of extract trips the room sources (AQS-CTL-003).', '',
 '| Room | Units | Area m2 | Volume m3 | Hazardous | Extract m3/h | ACH | Make-up m3/h | Governs | Fan kW (duty) |', '|---|---|---|---|---|---|---|---|---|---|']
md += [f"| {r['room']} | {r['units']} | {r['area_m2']} | {r['volume_m3']} | {r['hazardous']} | {r['extract_m3_h']} | {r['ach']} | {r['makeup_m3_h']} | {r['governs']} | {r['fan_kW']} |" for r in out]
tot = sum(r['fan_kW'] for r in out)
md += ['', f"{len(out)} rooms; total extract {sum(r['extract_m3_h'] for r in out):,} m3/h; duty fan power {tot:.2f} kW (standby fans idle). Life levels (HAB, FARM) also carry their own AHU duties in the graph (CRYO_AHU and farm AHU); this table is the room exhaust and make-up layer.",
 'Make-up air is tempered from the Q4 ladder in winter (99.6 % -7.2 C) and by the building chiller in summer (0.4 % 37.8 C), AQS-SITE-002.']
open('docs-authority/HVAC.md', 'w').write('\n'.join(md) + '\n'); print(len(out), round(tot, 2))
